<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/dashboard_layout.php';
$user=require_role('admin');
$kpis=db()->query("SELECT COALESCE(SUM(CASE WHEN payment_status='Paid' THEN total_amount ELSE 0 END),0) gmv,COALESCE(SUM(CASE WHEN order_status='Completed' THEN quantity_liters ELSE 0 END),0) liters,COALESCE(SUM(order_status NOT IN ('Completed','Cancelled')),0) active_orders FROM orders")->fetch();
$customers=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();
$onlineAgents=(int)sf_query("SELECT COUNT(*) FROM delivery_agent_profiles p JOIN users u ON u.id=p.user_id JOIN sf_agent_approvals a ON a.user_id=u.id WHERE p.is_online=1 AND u.status='active' AND a.approval_status='Approved'")->fetchColumn();
$inventory=db()->query('SELECT f.*,s.low_stock_liters,ROUND(stock_liters/NULLIF(tank_capacity,0)*100,1) stock_percent FROM fuel_inventory f JOIN sf_inventory_settings s ON s.fuel_id=f.id ORDER BY f.id')->fetchAll();
$lowStock=array_filter($inventory,fn($fuel)=>(float)$fuel['stock_liters']<=(float)$fuel['low_stock_liters']);
$recent=db()->query('SELECT o.*,c.full_name customer_name,a.full_name agent_name FROM orders o JOIN users c ON c.id=o.customer_id LEFT JOIN users a ON a.id=o.delivery_agent_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll();
$daily=db()->query("SELECT DATE(created_at) day,COUNT(*) orders_count,COALESCE(SUM(total_amount),0) amount FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
$maxDaily=max(array_merge([1],array_map('floatval',array_column($daily,'amount'))));
dashboard_start('Admin Command Center','dashboard',$user);
?>
<section class="welcome-panel"><div><span class="eyebrow">Macro operations</span><h2>The entire fuel network, in signal.</h2><p>Monitor commerce, litres, active tankers, customers and inventory risk from one protected command center.</p></div><a class="btn" href="<?= url('admin/manage_orders.php') ?>"><i class="fa-solid fa-bolt"></i> Dispatch Orders</a></section>
<?php if($lowStock): ?><div class="critical-banner"><i class="fa-solid fa-triangle-exclamation"></i><strong>Critical reserve alert:</strong> <?= count($lowStock) ?> fuel type<?= count($lowStock)===1?' is':'s are' ?> below the configured stock threshold. Open inventory control immediately.</div><?php endif; ?>
<section class="metrics-grid"><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-indian-rupee-sign"></i></span><div><strong data-counter="<?= (float)$kpis['gmv'] ?>" data-prefix="₹">₹0</strong><span>Gross Merchandise Value</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-droplet"></i></span><div><strong data-counter="<?= (float)$kpis['liters'] ?>" data-decimals="1" data-suffix=" L">0 L</strong><span>Total Litres Sold</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-truck-fast"></i></span><div><strong data-counter="<?= $onlineAgents ?>">0</strong><span>Active Tankers on Duty</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-users"></i></span><div><strong data-counter="<?= $customers ?>">0</strong><span>Registered Customers</span></div></article></section>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>7-Day Order Value</h2><span class="badge success">Live database</span></div><div class="chart"><?php foreach($daily as $day): ?><div class="chart-bar"><i style="height:<?= max(5,round((float)$day['amount']/$maxDaily*100)) ?>%"></i><span><?= e(date('D',strtotime($day['day']))) ?><br><?= money($day['amount']) ?></span></div><?php endforeach; ?></div></section><aside class="panel"><div class="panel-head"><h2>Inventory Reserve</h2><a href="<?= url('admin/inventory.php') ?>">Manage</a></div><div class="quick-actions"><?php foreach($inventory as $fuel): ?><div class="quick-action"><i class="fa-solid fa-gas-pump"></i><div style="width:100%"><strong><?= e($fuel['fuel_type']) ?> · <?= e($fuel['stock_percent']) ?>%</strong><small><?= number_format((float)$fuel['stock_liters']) ?> / <?= number_format((float)$fuel['tank_capacity']) ?> L</small><div class="stock-bar" style="margin-top:6px"><span style="width:<?= min(100,(float)$fuel['stock_percent']) ?>%"></span></div></div></div><?php endforeach; ?></div></aside></div>
<section class="panel"><div class="panel-head"><h2>Master Order Signal</h2><a href="<?= url('admin/manage_orders.php') ?>">Open full grid <i class="fa-solid fa-arrow-right"></i></a></div><div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Customer</th><th>Fuel</th><th>GMV</th><th>Agent</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $order): ?><tr><td><strong><?= e($order['tracking_code']) ?></strong></td><td><?= e($order['customer_name']) ?></td><td><?= e($order['fuel_type']) ?> · <?= e($order['quantity_liters']) ?> L</td><td class="money-tag"><?= money($order['total_amount']) ?></td><td><?= e($order['agent_name']?:'Unassigned') ?></td><td><span class="badge <?= status_class($order['order_status']) ?>"><?= e($order['order_status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php dashboard_end(); ?>
